// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadOswald = makeLoadFont('Oswald');

// Library: none — native interpolate/spring for a clean broadcast-style UI popup

const { fontFamily: interFamily } = loadInter();
const { fontFamily: oswaldFamily } = loadOswald();



export type PayoutPopupProps = Record<string, any>;

const PayoutPopup: React.FC<PayoutPopupProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 10,
  title = "STRAIGHT FLUSH PAYOUTS",
  accentColor = "#ff2a2a", // Inspired by the red neon boxes in the reference image
  cardBackgroundColor = "rgba(10, 15, 25, 0.95)",
  payouts = [
    { hand: "7 Card", payout: "8,000" },
    { hand: "6 Card", payout: "1,000" },
    { hand: "5 Card", payout: "100" },
    { hand: "4 Card", payout: "60" },
    { hand: "3 Card", payout: "7" },
  ],
  footerText = "All layout paytables are 'to 1'",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Animation: Main Card Entrance
  const cardEntrance = spring({
    frame,
    fps,
    config: { damping: 14, mass: 0.8 },
    durationInFrames: 30,
  });

  const cardScale = interpolate(cardEntrance, [0, 1], [0.8, 1]);
  const cardOpacity = interpolate(cardEntrance, [0, 1], [0, 1]);
  const cardY = interpolate(cardEntrance, [0, 1], [50 * s, 0]);

  // Dimensions
  const cardWidth = 800 * s;
  const paddingX = 60 * s;
  const paddingY = 50 * s;
  const borderRadius = 16 * s;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        justifyContent: "center",
        alignItems: "center",
        fontFamily: interFamily,
      }}
    >
      <div
        style={{
          width: cardWidth,
          backgroundColor: cardBackgroundColor,
          borderRadius: borderRadius,
          padding: `${paddingY}px ${paddingX}px`,
          display: "flex",
          flexDirection: "column",
          alignItems: "stretch",
          boxShadow: `0 ${20 * s}px ${50 * s}px rgba(0,0,0,0.5), 0 0 ${
            15 * s
          }px ${accentColor}40, inset 0 0 ${4 * s}px ${accentColor}80`,
          border: `${2 * s}px solid ${accentColor}`,
          opacity: cardOpacity,
          transform: `scale(${cardScale}) translateY(${cardY}px)`,
          transition: "none",
        }}
      >
        {/* Header */}
        <div
          style={{
            borderBottom: `${2 * s}px solid rgba(255, 255, 255, 0.1)`,
            paddingBottom: 24 * s,
            marginBottom: 30 * s,
            textAlign: "center",
          }}
        >
          <h2
            style={{
              margin: 0,
              fontFamily: oswaldFamily,
              fontSize: 52 * s,
              fontWeight: 700,
              color: "#ffffff",
              letterSpacing: 2 * s,
              textTransform: "uppercase",
              textShadow: `0 0 ${10 * s}px ${accentColor}80`,
            }}
          >
            {title}
          </h2>
        </div>

        {/* Payout List */}
        <div style={{ display: "flex", flexDirection: "column", gap: 16 * s }}>
          {payouts.map((item, index) => {
            // Staggered entrance for each row
            const itemEntrance = spring({
              frame: frame - 15 - index * 5, // Start after card entrance, stagger by 5 frames
              fps,
              config: { damping: 12 },
              durationInFrames: 25,
            });

            const itemOpacity = interpolate(itemEntrance, [0, 1], [0, 1]);
            const itemX = interpolate(itemEntrance, [0, 1], [-20 * s, 0]);

            return (
              <div
                key={index}
                style={{
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center",
                  padding: `${12 * s}px ${20 * s}px`,
                  backgroundColor:
                    index % 2 === 0
                      ? "rgba(255, 255, 255, 0.05)"
                      : "transparent",
                  borderRadius: 8 * s,
                  opacity: itemOpacity,
                  transform: `translateX(${itemX}px)`,
                  transition: "none",
                }}
              >
                <span
                  style={{
                    fontSize: 32 * s,
                    fontWeight: 600,
                    color: "#e2e8f0",
                  }}
                >
                  {item.hand}
                </span>
                <span
                  style={{
                    fontSize: 36 * s,
                    fontWeight: 800,
                    color: accentColor,
                    fontFamily: oswaldFamily,
                    letterSpacing: 1 * s,
                    textShadow: `0 0 ${8 * s}px ${accentColor}40`,
                  }}
                >
                  {item.payout}
                </span>
              </div>
            );
          })}
        </div>

        {/* Footer */}
        {footerText && (
          <div
            style={{
              marginTop: 40 * s,
              textAlign: "center",
            }}
          >
            <p
              style={{
                margin: 0,
                fontSize: 20 * s,
                color: "rgba(255, 255, 255, 0.5)",
                fontStyle: "italic",
                opacity: interpolate(cardEntrance, [0, 1], [0, 1], {
                  extrapolateLeft: "clamp",
                  extrapolateRight: "clamp",
                }),
              }}
            >
              {footerText}
            </p>
          </div>
        )}
      </div>
    </AbsoluteFill>
  );
};

export default PayoutPopup;